{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "The bill would require the comptroller’s office to review foundational literacy skills plans submitted to the Department of Education for approval. The review would check whether the plans meet the requirements of subsection 49-1-905(f) and state board rules.",
      "rationale": "Conveys the required reviewer, plans subject to review, and both compliance standards."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "It would also examine whether the department initially approved or denied each plan and what revisions the department required for approval.",
      "rationale": "In context, conveys the comptroller’s examination of initial approval decisions and required changes. 'Revisions' adequately encompasses amendments; omitting the option to use a designee does not materially change the review obligation."
    },
    {
      "proposition_id": "P3",
      "status": "partial",
      "summary_quote": "Every three years, the comptroller would report the review findings",
      "rationale": "Conveys reporting of review findings, but does not clearly establish that the literacy-plan findings must be included in the same report as the broader review findings."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "The comptroller’s office would also review data, practices, and outcomes related to the provisions covered by the bill.",
      "rationale": "Identifies the reviewer and subjects of review, but describes the scope as the provisions covered by the bill rather than the entire statutory part containing § 49-1-910."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "The department would have to provide requested information as soon as practicable.",
      "rationale": "In context, conveys the Department of Education’s obligation to provide information requested by the comptroller’s office and the required timing."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "Every three years, the comptroller would report the review findings to the specified Senate and House education committee chairs and the state board of education, and publish the report on its website.",
      "rationale": "Conveys the reporting interval, findings, Senate recipient, state board recipient, and website publication. It substitutes a House education committee chair for the chair of the House committee having jurisdiction over student literacy."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "The bill would take effect upon becoming law.",
      "rationale": "Accurately conveys the effective-date provision."
    }
  ]
}
